`timescale 1ns/1ps
`default_nettype none

// Contract test for the isolated DS2 reader.  The DS1 reference file is
// generated by python/ds12_stream_reference.py and loaded as NHWC bytes; the
// bank under test is the real synchronous ds12_stream_activation_banks.
module tb_ds12_stream_ds2_window_reader;
    localparam integer BANK_WORDS = 8192;
    localparam integer BANK_BYTES = BANK_WORDS * 4;
    localparam integer WINDOWS = 16 * 16;
    localparam integer VECTORS_PER_WINDOW = 18;
    localparam integer TOTAL_VECTORS = WINDOWS * VECTORS_PER_WINDOW;

    reg clk = 1'b0;
    reg rst_n = 1'b0;
    always #5 clk = ~clk;

    reg start_valid, start_bank, start_last;
    reg [5:0] start_row, start_col;
    reg [31:0] start_epoch;
    wire start_ready;
    wire win_valid;
    reg win_ready;
    wire [127:0] win_data;
    wire [5:0] win_row, win_col;
    wire [1:0] win_tap_row, win_tap_col;
    wire win_slice, win_owner, win_last;
    wire [1:0] win_context;
    wire [31:0] win_epoch;
    wire read_req_valid, read_req_ready, read_req_bank;
    wire [31:0] read_req_epoch, read_req_addr;
    wire read_resp_valid, read_resp_ready, read_resp_bank;
    wire [31:0] read_resp_data, read_resp_epoch, read_resp_addr;
    wire busy;
    wire [3:0] context_active, context_peak;
    wire [31:0] read_count, window_count;
    wire reader_error;
    wire [7:0] reader_error_code;

    reg bank_start_valid, bank_start_bank;
    reg [31:0] bank_start_epoch, bank_start_expected;
    wire bank_start_ready;
    reg bank_write_valid, bank_write_bank, bank_write_last;
    reg [31:0] bank_write_epoch, bank_write_addr, bank_write_data;
    reg [3:0] bank_write_be;
    wire bank_write_ready, bank_write_resp_valid;
    reg bank_write_resp_ready;
    wire bank_commit_ready, bank_commit_done;
    reg bank_commit_valid, bank_commit_bank;
    reg [31:0] bank_commit_epoch;
    wire [1:0] bank0_state, bank1_state;
    wire [31:0] bank0_epoch, bank1_epoch, bank_error_count;
    wire bank_error;
    wire [7:0] bank_error_code;
    wire [31:0] bank_write_count, bank_expected_bytes;
    wire bank_write_last_seen;
    wire [31:0] bank_wr_resp_epoch, bank_wr_resp_addr;
    wire bank_wr_resp_bank;

    reg [7:0] expected [0:BANK_BYTES-1];
    integer i, b, waits, cycles, starts_sent, vectors_seen, mismatches;
    integer pixel, expected_byte, iy, ix, ch;
    reg [31:0] lfsr;
    reg seen [0:WINDOWS-1][0:8][0:1];
    reg [31:0] word;

    ds12_stream_activation_banks #(.BANK_WORDS(BANK_WORDS)) bank (
        .clk(clk), .rst_n(rst_n),
        .layer_start_valid(bank_start_valid), .layer_start_ready(bank_start_ready),
        .layer_start_bank(bank_start_bank), .layer_start_epoch(bank_start_epoch),
        .layer_start_expected_bytes(bank_start_expected),
        .write_valid(bank_write_valid), .write_ready(bank_write_ready),
        .write_bank(bank_write_bank), .write_epoch(bank_write_epoch),
        .write_addr(bank_write_addr), .write_data(bank_write_data),
        .write_be(bank_write_be), .write_last(bank_write_last),
        .write_resp_valid(bank_write_resp_valid), .write_resp_ready(bank_write_resp_ready),
        .write_resp_bank(bank_wr_resp_bank), .write_resp_epoch(bank_wr_resp_epoch),
        .write_resp_addr(bank_wr_resp_addr),
        .commit_valid(bank_commit_valid), .commit_ready(bank_commit_ready),
        .commit_bank(bank_commit_bank), .commit_epoch(bank_commit_epoch),
        .commit_done(bank_commit_done),
        .read_req_valid(read_req_valid), .read_req_ready(read_req_ready),
        .read_req_bank(read_req_bank), .read_req_epoch(read_req_epoch),
        .read_req_addr(read_req_addr), .read_resp_valid(read_resp_valid),
        .read_resp_ready(read_resp_ready), .read_resp_data(read_resp_data),
        .read_resp_bank(read_resp_bank), .read_resp_epoch(read_resp_epoch),
        .read_resp_addr(read_resp_addr), .bank0_state(bank0_state),
        .bank1_state(bank1_state), .bank0_epoch(bank0_epoch), .bank1_epoch(bank1_epoch),
        .write_epoch_active(), .write_count(bank_write_count),
        .write_expected_bytes(bank_expected_bytes), .write_last_seen(bank_write_last_seen),
        .error(bank_error), .error_code(bank_error_code)
    );

    ds12_stream_ds2_window_reader #(.CONTEXTS(4)) dut (
        .clk(clk), .rst_n(rst_n),
        .window_start_valid(start_valid), .window_start_ready(start_ready),
        .window_start_row(start_row), .window_start_col(start_col),
        .window_start_bank(start_bank), .window_start_epoch(start_epoch),
        .window_start_last(start_last),
        .window_valid(win_valid), .window_ready(win_ready), .window_data(win_data),
        .window_row(win_row), .window_col(win_col), .window_tap_row(win_tap_row),
        .window_tap_col(win_tap_col), .window_channel_slice(win_slice),
        .window_context(win_context), .window_owner(win_owner),
        .window_epoch(win_epoch), .window_last(win_last),
        .read_req_valid(read_req_valid), .read_req_ready(read_req_ready),
        .read_req_bank(read_req_bank), .read_req_epoch(read_req_epoch),
        .read_req_addr(read_req_addr), .read_resp_valid(read_resp_valid),
        .read_resp_ready(read_resp_ready), .read_resp_data(read_resp_data),
        .read_resp_bank(read_resp_bank), .read_resp_epoch(read_resp_epoch),
        .read_resp_addr(read_resp_addr), .busy(busy), .context_active(context_active),
        .context_peak(context_peak), .read_count(read_count), .window_count(window_count),
        .error(reader_error), .error_code(reader_error_code)
    );

    always @(negedge clk) begin
        if (!rst_n) begin
            win_ready <= 1'b0;
            lfsr <= 32'h7a31c5e1;
        end else begin
            // Consumer backpressure is deliberately irregular.  A stalled
            // output is checked on every cycle by the posedge scoreboard.
            win_ready <= (lfsr[2:0] != 3'b000);
            lfsr <= {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
        end
    end

    task reset_dut;
        begin
            rst_n = 1'b0; bank_start_valid = 0; bank_write_valid = 0;
            bank_commit_valid = 0; start_valid = 0; cycles = 0;
            repeat (3) @(posedge clk);
            @(negedge clk); rst_n = 1'b1;
        end
    endtask

    task start_bank_layer;
        begin
            @(negedge clk); bank_start_bank = 1'b1; bank_start_epoch = 32'h11;
            bank_start_expected = BANK_BYTES; bank_start_valid = 1'b1;
            while (!bank_start_ready) @(negedge clk);
            @(posedge clk); @(negedge clk); bank_start_valid = 1'b0;
        end
    endtask

    task send_write;
        input integer wi;
        begin
            @(negedge clk); bank_write_bank = 1'b1; bank_write_epoch = 32'h11;
            bank_write_addr = wi * 4; bank_write_data = 32'h0;
            bank_write_data[7:0] = expected[wi*4];
            bank_write_data[15:8] = expected[wi*4+1];
            bank_write_data[23:16] = expected[wi*4+2];
            bank_write_data[31:24] = expected[wi*4+3];
            bank_write_be = 4'hf; bank_write_last = (wi == BANK_WORDS-1);
            bank_write_valid = 1'b1; waits = 0;
            while (!bank_write_ready) begin
                waits = waits + 1;
                if (waits > 1000) $fatal(1, "write timeout word=%0d", wi);
                @(negedge clk);
            end
            @(posedge clk); @(negedge clk); bank_write_valid = 1'b0;
        end
    endtask

    task commit_bank_layer;
        begin
            while (bank_write_resp_valid) @(posedge clk);
            @(negedge clk); bank_commit_bank = 1'b1; bank_commit_epoch = 32'h11;
            bank_commit_valid = 1'b1;
            while (!bank_commit_ready) @(negedge clk);
            @(posedge clk); @(negedge clk); bank_commit_valid = 1'b0;
            repeat (2) @(posedge clk);
        end
    endtask

    task start_window;
        input integer r;
        input integer c;
        begin
            @(negedge clk); start_row = r; start_col = c; start_bank = 1'b1;
            start_epoch = 32'h11; start_last = (r == 15 && c == 15);
            start_valid = 1'b1;
            while (!start_ready) @(negedge clk);
            @(posedge clk); @(negedge clk); start_valid = 1'b0;
            starts_sent = starts_sent + 1;
        end
    endtask

    always @(posedge clk) begin
        if (rst_n) begin
            cycles = cycles + 1;
            if (win_valid && win_ready) begin
                if (win_row >= 16 || win_col >= 16 || win_tap_row >= 3 || win_tap_col >= 3) begin
                    mismatches = mismatches + 1;
                    $display("BAD metadata row=%0d col=%0d tap=%0d,%0d", win_row, win_col, win_tap_row, win_tap_col);
                end else begin
                    pixel = win_row * 16 + win_col;
                    if (seen[pixel][win_tap_row*3+win_tap_col][win_slice]) begin
                        mismatches = mismatches + 1;
                        $display("DUP vector pixel=%0d tap=%0d slice=%0d", pixel, win_tap_row*3+win_tap_col, win_slice);
                    end
                    seen[pixel][win_tap_row*3+win_tap_col][win_slice] = 1'b1;
                    for (b = 0; b < 16; b = b + 1) begin
                        iy = win_row * 2 + win_tap_row - 1;
                        ix = win_col * 2 + win_tap_col - 1;
                        ch = win_slice * 16 + b;
                        if (iy < 0 || iy >= 32 || ix < 0 || ix >= 32)
                            expected_byte = 0;
                        else
                            expected_byte = expected[(iy * 32 + ix) * 32 + ch];
                        if (win_data[b*8 +: 8] !== expected_byte[7:0]) begin
                            mismatches = mismatches + 1;
                            if (mismatches < 10)
                                $display("DATA mismatch p=%0d tap=%0d slice=%0d byte=%0d got=%02x exp=%02x", pixel, win_tap_row*3+win_tap_col, win_slice, b, win_data[b*8 +: 8], expected_byte[7:0]);
                        end
                    end
                    if (win_owner !== 1'b1 || win_epoch !== 32'h11 || win_context > 3) begin
                        mismatches = mismatches + 1;
                        $display("TAG mismatch owner=%0d epoch=%h context=%0d", win_owner, win_epoch, win_context);
                    end
                    vectors_seen = vectors_seen + 1;
                end
            end
        end
    end

    initial begin
        starts_sent = 0; vectors_seen = 0; mismatches = 0;
        bank_write_resp_ready = 1'b1;
        bank_start_bank = 0; bank_start_epoch = 0; bank_start_expected = 0;
        bank_write_bank = 0; bank_write_epoch = 0; bank_write_addr = 0;
        bank_write_data = 0; bank_write_be = 0; bank_write_last = 0;
        bank_commit_bank = 0; bank_commit_epoch = 0;
        start_row = 0; start_col = 0; start_bank = 0; start_epoch = 0; start_last = 0;
        for (i = 0; i < BANK_BYTES; i = i + 1) expected[i] = 0;
        for (i = 0; i < WINDOWS; i = i + 1)
            for (b = 0; b < 9; b = b + 1) begin
                seen[i][b][0] = 0; seen[i][b][1] = 0;
            end
        $readmemh("build/ds12_stream_ds2_window_reader/ds12_stream_ds1_output_i8.hex", expected);

        reset_dut;
        $display("TB reset done");
        start_bank_layer;
        $display("TB bank start done");
        for (i = 0; i < BANK_WORDS; i = i + 1) send_write(i);
        $display("TB bank load done count=%0d", bank_write_count);
        if (bank_write_count !== BANK_BYTES || !bank_write_last_seen)
            $fatal(1, "DS1 bank load failed count=%0d last=%0d", bank_write_count, bank_write_last_seen);
        commit_bank_layer;
        $display("TB bank commit done state=%0d epoch=%h", bank1_state, bank1_epoch);
        if (bank1_state !== 2'd1 || bank1_epoch !== 32'h11 || bank_error)
            $fatal(1, "bank commit failed state=%0d epoch=%h err=%0d code=%h", bank1_state, bank1_epoch, bank_error, bank_error_code);

        // Four slots are intentionally exercised by issuing the complete
        // raster through the start interface while the reader drains it.
        for (i = 0; i < WINDOWS; i = i + 1) begin
            start_window(i / 16, i % 16);
            if ((i % 32) == 31) $display("TB starts=%0d vectors=%0d cycles=%0d active=%0d reads=%0d", starts_sent, vectors_seen, cycles, context_active, read_count);
        end
        while (vectors_seen < TOTAL_VECTORS) begin
            if (cycles > 80000) $fatal(1, "reader timeout vectors=%0d starts=%0d", vectors_seen, starts_sent);
            @(posedge clk);
        end
        for (i = 0; i < WINDOWS; i = i + 1)
            for (b = 0; b < 9; b = b + 1)
                if (!seen[i][b][0] || !seen[i][b][1]) mismatches = mismatches + 1;
        if (mismatches != 0 || reader_error || bank_error)
            $fatal(1, "FAIL mismatches=%0d reader_error=%0d code=%h bank_error=%0d code=%h", mismatches, reader_error, reader_error_code, bank_error, bank_error_code);
        $display("PASS ds12_stream_ds2_window_reader windows=%0d vectors=%0d bytes_checked=%0d reads=%0d cycles=%0d context_peak=%0d backpressure=random bank_epoch=%h", WINDOWS, vectors_seen, TOTAL_VECTORS*16, read_count, cycles, context_peak, bank1_epoch);
        $finish(0);
    end
endmodule

`default_nettype wire
